  1	import type {IncomingMessage, ListSessionsMessage} from '../../types/messages.js';
  2	import type {SessionCursor} from '../../types/sessionStore.js';
  3	
  4	const MAX_CONTENT_LENGTH = 10000;
  5	const MAX_SESSION_ID_LENGTH = 128;
  6	
  7	interface ValidationSuccess {
  8	  valid: true;
  9	  data: IncomingMessage;
 10	}
 11	
 12	interface ValidationFailure {
 13	  valid: false;
 14	  error: string;
 15	}
 16	
 17	export type ValidationResult = ValidationSuccess | ValidationFailure;
 18	
 19	export function validateMessage(payload: unknown): ValidationResult {
 20	  if (typeof payload !== 'object' || payload === null) {
 21	    return {valid: false, error: 'Message must be an object'};
 22	  }
 23	
 24	  const message = payload as Record<string, unknown>;
 25	
 26	  if (typeof message.type !== 'string') {
 27	    return {valid: false, error: 'Message must have a type field'};
 28	  }
 29	
 30	  switch (message.type) {
 31	    case 'user_message':
 32	      return validateUserMessage(message);
 33	    case 'ping':
 34	      return validatePingMessage(message);
 35	    case 'list_sessions':
 36	      return validateListSessionsMessage(message);
 37	    default:
 38	      return {valid: false, error: `Unknown message type: ${message.type}`};
 39	  }
 40	}
 41	
 42	function validateUserMessage(message: Record<string, unknown>): ValidationResult {
 43	  if (typeof message.content !== 'string') {
 44	    return {valid: false, error: 'user_message must have content string'};
 45	  }
 46	
 47	  const trimmed = message.content.trim();
 48	
 49	  if (trimmed.length === 0) {
 50	    return {valid: false, error: 'Message content cannot be empty'};
 51	  }
 52	
 53	  if (message.content.length > MAX_CONTENT_LENGTH) {
 54	    return {valid: false, error: `Message content too long (max ${MAX_CONTENT_LENGTH} chars)`};
 55	  }
 56	
 57	  return {
 58	    valid: true,
 59	    data: {
 60	      type: 'user_message',
 61	      content: message.content,
 62	    },
 63	  };
 64	}
 65	
 66	function validatePingMessage(message: Record<string, unknown>): ValidationResult {
 67	  if (typeof message.timestamp !== 'number') {
 68	    return {valid: false, error: 'ping must have timestamp number'};
 69	  }
 70	
 71	  return {
 72	    valid: true,
 73	    data: {
 74	      type: 'ping',
 75	      timestamp: message.timestamp,
 76	    },
 77	  };
 78	}
 79	
 80	function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
 81	  const data: ListSessionsMessage = {type: 'list_sessions'};
 82	
 83	  if (message.limit !== undefined) {
 84	    if (typeof message.limit !== 'number' || !Number.isInteger(message.limit) || message.limit < 0) {
 85	      return {valid: false, error: 'list_sessions limit must be a non-negative integer'};
 86	    }
 87	    data.limit = message.limit;
 88	  }
 89	
 90	  if (message.before !== undefined) {
 91	    const before = parseCursor(message.before);
 92	    if (!before) {
 93	      return {valid: false, error: 'list_sessions before must be a {updatedAt, sessionId} cursor'};
 94	    }
 95	    data.before = before;
 96	  }
 97	
 98	  return {valid: true, data};
 99	}
100	
101	function parseCursor(value: unknown): SessionCursor | undefined {
102	  if (typeof value !== 'object' || value === null) return undefined;
103	  const {updatedAt, sessionId} = value as Record<string, unknown>;
104	  if (typeof sessionId !== 'string' || sessionId.length < 1 || sessionId.length > MAX_SESSION_ID_LENGTH)
105	    return undefined;
106	  if (typeof updatedAt !== 'string' && typeof updatedAt !== 'number') return undefined;
107	  if (!Number.isFinite(new Date(updatedAt).getTime())) return undefined;
108	  return {updatedAt, sessionId};
109	}
  1	import {validateMessage} from './validation.js';
  2	
  3	// One wire name for the client frame: the alias is gone, and the frame the validator returns is the exported shape.
  4	
  5	describe('the websocket frame validator', () => {
  6	  it('accepts user_message and returns the frame the exported union describes', () => {
  7	    const result = validateMessage({type: 'user_message', content: 'hello'});
  8	
  9	    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
 10	  });
 11	
 12	  it('rejects send_message, which is no longer a wire name', () => {
 13	    const result = validateMessage({type: 'send_message', content: 'hello'});
 14	
 15	    expect(result).toEqual({valid: false, error: 'Unknown message type: send_message'});
 16	  });
 17	
 18	  it('drops any field the frame does not define, rather than forwarding it', () => {
 19	    const result = validateMessage({type: 'user_message', content: 'hello', chatId: 'c1'});
 20	
 21	    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
 22	  });
 23	});
 24	
 25	describe('validating a list_sessions frame', () => {
 26	  it('forwards limit and a before cursor, drops a client userId, and refuses a malformed limit or cursor', () => {
 27	    const before = {updatedAt: '2026-01-01T00:05:00.000Z', sessionId: 's3'};
 28	    const badCursors = [
 29	      ...['', 'a'.repeat(129)].map(sessionId => ({updatedAt: before.updatedAt, sessionId})),
 30	      ...['not-a-date', true, Number.NaN].map(updatedAt => ({updatedAt, sessionId: 's1'})),
 31	    ];
 32	    const refused = [
 33	      ...['ten', -1, 1.5].map(limit => ({type: 'list_sessions', limit})),
 34	      ...['not-an-object', null, ...badCursors].map(cursor => ({type: 'list_sessions', before: cursor})),
 35	    ];
 36	
 37	    expect({
 38	      bare: validateMessage({type: 'list_sessions'}),
 39	      full: validateMessage({type: 'list_sessions', limit: 0, before, userId: 'u2'}),
 40	      epoch: validateMessage({type: 'list_sessions', before: {updatedAt: 1767225900000, sessionId: 's3', extra: 1}}),
 41	      refused: refused.map(frame => validateMessage(frame).valid),
 42	    }).toEqual({
 43	      bare: {valid: true, data: {type: 'list_sessions'}},
 44	      full: {valid: true, data: {type: 'list_sessions', limit: 0, before}},
 45	      epoch: {valid: true, data: {type: 'list_sessions', before: {updatedAt: 1767225900000, sessionId: 's3'}}},
 46	      refused: Array(refused.length).fill(false),
 47	    });
 48	  });
 49	});

