     1	import {WebSocket} from 'ws';
     2	import type {SessionEntry} from '../../types/session.js';
     3	import type {ChatSession} from '../../types/session.js';
     4	import {ErrorCodes} from '../../types/messages.js';
     5	import type {ListSessionsMessage, OutgoingMessage} from '../../types/messages.js';
     6	import type {SessionStore} from '../../types/sessionStore.js';
     7	import {ThinkingTagParser, ParsedSegment} from '../../infrastructure/parsers/thinkingTagParser.js';
     8	import {validateMessage} from './validation.js';
     9	import type {ValidationResult} from './validation.js';
    10	import {PerSessionLock} from '../../shared/perSessionLock.js';
    11	import type {ChatOrchestrator} from '../../orchestration/chatOrchestrator.js';
    12	import {AIError} from '../../types/ai.js';
    13	import type {MessageChunk} from '../../types/ai.js';
    14	import {
    15	  createUserEntry,
    16	  createAssistantEntry,
    17	  createThinkingEntry,
    18	  createToolEntry,
    19	} from '../../orchestration/entryFactories.js';
    20	import {appendEntry, appendDelta, commitEntry, markTruncated} from '../../orchestration/entryMutations.js';
    21	import {
    22	  sendJson,
    23	  sendUpsert,
    24	  sendDelta,
    25	  sendCommit,
    26	  sendSkip,
    27	  sendError,
    28	  sendStreamEnd,
    29	  sendSessionList,
    30	} from './sender.js';
    31	import {log} from '../../shared/logger.js';
    32	
    33	interface StreamState {
    34	  thinkingIndex: number | null;
    35	  assistantIndex: number | null;
    36	  suppressOutput: boolean;
    37	  sentAssistantIndices: number[];
    38	}
    39	
    40	type StateIndexKey = 'thinkingIndex' | 'assistantIndex';
    41	type EntryFactory = typeof createThinkingEntry | typeof createAssistantEntry;
    42	export function createMessageHandler(orchestrator: ChatOrchestrator, sessionStore?: SessionStore) {
    43	  // Keyed by session, not socket: a resumed session can be open on more than one (specs/hal-engine-architecture/spec.md).
    44	  const lock = new PerSessionLock();
    45	  return function handleMessage(
    46	    ws: WebSocket,
    47	    session: ChatSession,
    48	    rawMessage: unknown,
    49	    signal?: AbortSignal
    50	  ): Promise<void> {
    51	    const validation = validateMessage(rawMessage);
    52	    // Queued with no await before it, so a session's user_messages, a failed one too, are answered in arrival order.
    53	    if (isUserMessageFrame(rawMessage)) {
    54	      return lock.run(session.sessionId, () => answerInTurn(ws, session, orchestrator, validation, signal));
    55	    }
    56	    // An async action runs up to its first await at once, so a ping is answered now and a throw stays a rejection.
    57	    return wsErrorHandler(ws, async () => {
    58	      // Off the lock: a list is not a turn, so it never queues behind a streaming answer.
    59	      if (validation.valid && validation.data.type === 'list_sessions') {
    60	        return answerListSessions(ws, session, sessionStore, validation.data);
    61	      }
    62	      answerFrame(ws, validation);
    63	    });
    64	  };
    65	}
    66	
    67	// The user is the session's, which the upgrade authenticated; the frame never names one.
    68	async function answerListSessions(
    69	  ws: WebSocket,
    70	  session: ChatSession,
    71	  sessionStore: SessionStore | undefined,
    72	  {limit, before}: ListSessionsMessage
    73	): Promise<void> {
    74	  const summaries = (await sessionStore?.listFor?.(session.userId, {limit, before})) ?? [];
    75	  sendSessionList(ws, summaries);
    76	}
    77	
    78	// The whole answer, an error and the stream_end included, goes out inside the lock: an error frame names no message.
    79	async function answerInTurn(
    80	  ws: WebSocket,
    81	  session: ChatSession,
    82	  orchestrator: ChatOrchestrator,
    83	  validation: ValidationResult,
    84	  signal: AbortSignal | undefined
    85	): Promise<void> {
    86	  // Its socket closed while it waited: nobody is left to read the answer, and a session's last close took its credentials.
    87	  if (signal?.aborted || ws.readyState === WebSocket.CLOSING || ws.readyState === WebSocket.CLOSED) {
    88	    log.info('message', 'queued message dropped: its socket closed', {sessionId: session.sessionId});
    89	    return;
    90	  }
    91	  const startedAt = Date.now();
    92	  try {
    93	    await wsErrorHandler(ws, () => answerUserMessage(ws, session, orchestrator, validation, signal));
    94	  } finally {
    95	    endTurn(ws, session, signal, startedAt);
    96	  }
    97	}
    98	
    99	// A turn whose socket closed is abandoned rather than ended: nobody is left to read a terminal frame.
   100	function endTurn(ws: WebSocket, session: ChatSession, signal: AbortSignal | undefined, startedAt: number): void {
   101	  if (signal?.aborted) {
   102	    log.info('message', 'turn abandoned: its socket closed', {
   103	      sessionId: session.sessionId,
   104	      elapsedMs: Date.now() - startedAt,
   105	    });
   106	    return;
   107	  }
   108	  sendStreamEnd(ws);
   109	}
   110	
   111	async function answerUserMessage(
   112	  ws: WebSocket,
   113	  session: ChatSession,
   114	  orchestrator: ChatOrchestrator,
   115	  validation: ValidationResult,
   116	  signal: AbortSignal | undefined
   117	): Promise<void> {
   118	  const message = validation.valid ? validation.data : undefined;
   119	  if (message?.type === 'user_message') return handleUserMessage(ws, session, orchestrator, message.content, signal);
   120	  answerFrame(ws, validation);
   121	}
   122	
   123	function answerFrame(ws: WebSocket, validation: ValidationResult): void {
   124	  if (!validation.valid) {
   125	    log.warn('message', 'validation failed', {error: validation.error});
   126	    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
   127	    return;
   128	  }
   129	
   130	  const message = validation.data;
   131	  if (message.type === 'ping') handlePing(ws, message.timestamp);
   132	}
   133	
   134	// Read from the raw frame, so a user_message that fails validation still gets its stream_end.
   135	function isUserMessageFrame(rawMessage: unknown): boolean {
   136	  return typeof rawMessage === 'object' && rawMessage !== null && Reflect.get(rawMessage, 'type') === 'user_message';
   137	}
   138	
   139	async function wsErrorHandler(ws: WebSocket, action: () => Promise<void>): Promise<void> {
   140	  try {
   141	    await action();
   142	  } catch (error) {
   143	    const message = error instanceof Error ? error.message : 'Unknown error';
   144	    const code = error instanceof AIError ? error.code : 'UNKNOWN';
   145	    log.error('message', 'handling error', {error: message, code});
   146	    if (error instanceof AIError && error.code === 'RATE_LIMITED') {
   147	      sendError(ws, ErrorCodes.RATE_LIMITED, 'AI service is busy, please try again');
   148	      return;
   149	    }
   150	    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to process message');
   151	  }
   152	}
   153	
   154	async function handleUserMessage(
   155	  ws: WebSocket,
   156	  session: ChatSession,
   157	  orchestrator: ChatOrchestrator,
   158	  content: string,
   159	  signal: AbortSignal | undefined
   160	): Promise<void> {
   161	  log.info('message', 'user message received', {sessionId: session.sessionId, contentLength: content.length});
   162	
   163	  const userEntry = createUserEntry(content);
   164	  const userIndex = appendEntry(session, userEntry);
   165	  sendUpsert(ws, userIndex, userEntry);
   166	
   167	  const parser = new ThinkingTagParser();
   168	  const state: StreamState = {
   169	    thinkingIndex: null,
   170	    assistantIndex: null,
   171	    suppressOutput: false,
   172	    sentAssistantIndices: [],
   173	  };
   174	
   175	  let textChunkCount = 0;
   176	
   177	  try {
   178	    for await (const chunk of orchestrator.processMessageStream(session, {signal})) {
   179	      // Its socket closed: breaking returns the run's generator, so the run stops and its own teardown still runs.
   180	      if (signal?.aborted) break;
   181	      textChunkCount = logChunk(chunk, textChunkCount);
   182	      processChunk(ws, session, state, parser, chunk);
   183	    }
   184	  } finally {
   185	    // Anything still open here was cut short: a stop has already flushed the parser and committed every entry it opened.
   186	    flushHeldText(ws, session, state, parser);
   187	    closeCutOff(ws, session, state, 'thinkingIndex');
   188	    closeCutOff(ws, session, state, 'assistantIndex');
   189	  }
   190	
   191	  if (textChunkCount > 0) {
   192	    log.debug('stream', `received ${textChunkCount} text chunks`);
   193	  }
   194	  log.info('stream', 'stream completed', {suppressed: state.suppressOutput, entries: session.entries.length});
   195	}
   196	
   197	// Diagnostics only: counts a run of text chunks so it is logged once, not per token.
   198	function logChunk(chunk: MessageChunk, textChunkCount: number): number {
   199	  if (chunk.type === 'text') return textChunkCount + 1;
   200	
   201	  if (textChunkCount > 0) {
   202	    log.debug('stream', `received ${textChunkCount} text chunks`);
   203	  }
   204	
   205	  if (chunk.type === 'tool_result') {
   206	    log.debug('stream', 'tool_result chunk', {
   207	      messageCount: chunk.clientMessages.length,
   208	      types: chunk.clientMessages.map(m => m.type),
   209	    });
   210	    return 0;
   211	  }
   212	
   213	  log.debug('stream', 'chunk', {type: chunk.type});
   214	  return 0;
   215	}
   216	
   217	function processChunk(
   218	  ws: WebSocket,
   219	  session: ChatSession,
   220	  state: StreamState,
   221	  parser: ThinkingTagParser,
   222	  chunk: MessageChunk
   223	): void {
   224	  if (chunk.type === 'text') return processTextChunk(ws, session, state, parser, chunk.text);
   225	  if (chunk.type === 'tool_use') return processToolUseChunk(ws, session, chunk.toolCall);
   226	  if (chunk.type === 'tool_result') return processToolResultChunk(ws, chunk.clientMessages);
   227	  if (chunk.type === 'suppress_output') return processSuppressChunk(ws, session, state);
   228	  if (chunk.type === 'stop') return processStopChunk(ws, session, state, parser);
   229	}
   230	
   231	function processTextChunk(
   232	  ws: WebSocket,
   233	  session: ChatSession,
   234	  state: StreamState,
   235	  parser: ThinkingTagParser,
   236	  text: string
   237	): void {
   238	  const segments = parser.push(text);
   239	  for (const segment of segments) {
   240	    handleTextSegment(ws, session, state, segment);
   241	  }
   242	}
   243	
   244	function handleTextSegment(ws: WebSocket, session: ChatSession, state: StreamState, segment: ParsedSegment): void {
   245	  if (segment.type === 'thinking') {
   246	    streamSegment(ws, session, state, 'thinkingIndex', createThinkingEntry, segment.content);
   247	    return;
   248	  }
   249	  commitAndClear(ws, session, state, 'thinkingIndex');
   250	  streamSegment(ws, session, state, 'assistantIndex', createAssistantEntry, segment.content);
   251	}
   252	
   253	function streamSegment(
   254	  ws: WebSocket,
   255	  session: ChatSession,
